-- 0059 — Dix-septième lot de recettes du catalogue (publiées et validées) :
-- soupes-repas et boîtes-repas à emporter, au moins 20 g de protéines par part (calcul Ciqual).
-- Fichier GÉNÉRÉ par scripts/generate-recipes-lot17.py depuis scripts/data/recipes-lot17.py.
-- Recettes originales (D7). Ne jamais éditer une fois appliqué.
-- 20 recettes, 211 lignes d'ingrédients, 92 étapes.

insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('soupe-lentilles-vertes-lardons-carottes', 'Soupe de lentilles vertes aux lardons et carottes', 'Une soupe épaisse de lentilles vertes mijotées avec des lardons, des carottes, du poireau et du thym. Rassasiante, et encore meilleure le lendemain.', 'Se garde 3 jours au réfrigérateur ou 2 mois au congélateur ; se réchauffe très bien.', 2, 10, 35, array['soupe', 'plat', 'lunch-box', 'economique']::text[]),
  ('minestrone-hiver-haricots-rouges-pates', 'Minestrone d''hiver aux haricots rouges et petites pâtes', 'Une soupe de légumes d''hiver à la tomate, avec des haricots rouges, des petites pâtes et beaucoup de parmesan. Un repas complet dans le bol.', 'Se garde 3 jours au réfrigérateur ; les pâtes gonflent, ajouter un peu d''eau en réchauffant.', 2, 15, 30, array['soupe', 'plat', 'lunch-box', 'economique']::text[]),
  ('veloute-butternut-pois-chiches-feta', 'Velouté de butternut, pois chiches grillés et feta', 'Un velouté de courge butternut au fromage blanc, garni de pois chiches dorés au paprika et de feta émiettée pour le croquant et les protéines.', 'Le velouté se garde 3 jours au réfrigérateur ; garder les pois chiches à part pour qu''ils restent croquants.', 2, 15, 30, array['soupe', 'plat', 'lunch-box']::text[]),
  ('soupe-thai-poulet-coco-nouilles', 'Soupe thaï au poulet, coco et nouilles de riz', 'Un bouillon au lait de coco et à la pâte de curry, avec du poulet émincé, des champignons, des carottes et des nouilles de riz, relevé de citron vert.', 'Le bouillon se garde 3 jours au réfrigérateur ; ajouter les nouilles au moment de réchauffer.', 2, 10, 20, array['soupe', 'plat', 'lunch-box', 'monde']::text[]),
  ('soupe-poireaux-pommes-de-terre-jambon', 'Soupe de poireaux et pommes de terre au jambon', 'La soupe poireaux-pommes de terre du quotidien, mixée au lait, avec des lanières de jambon et de l''emmental râpé pour en faire un vrai dîner.', 'Se garde 3 jours au réfrigérateur ; ajouter le jambon et le fromage au moment de servir.', 2, 15, 25, array['soupe', 'plat', 'lunch-box', 'economique']::text[]),
  ('harira-express-lentilles-pois-chiches', 'Harira express aux lentilles et pois chiches', 'Une soupe marocaine épaisse de lentilles corail, pois chiches et tomate, parfumée au cumin, au curcuma et au gingembre, finie au citron et à la coriandre.', 'Se garde 3 jours au réfrigérateur ou 2 mois au congélateur.', 2, 10, 30, array['soupe', 'plat', 'lunch-box', 'economique', 'monde']::text[]),
  ('soupe-poulet-petites-pates-carottes', 'Soupe de poulet aux petites pâtes et carottes', 'Un bouillon de volaille où cuisent du poulet, des carottes, du poireau et des petites pâtes, au thym. Le réconfort en bol, qui voyage bien en thermos.', 'Se garde 3 jours au réfrigérateur ; ajouter un peu d''eau en réchauffant.', 2, 10, 25, array['soupe', 'plat', 'lunch-box', 'economique']::text[]),
  ('soupe-patate-douce-lentilles-gingembre', 'Soupe de patate douce, lentilles corail et gingembre', 'Une soupe veloutée de patate douce et de lentilles corail au gingembre et au lait de coco, servie avec une cuillerée de yaourt et des graines de sésame.', 'Se garde 3 jours au réfrigérateur ou 2 mois au congélateur.', 2, 10, 25, array['soupe', 'plat', 'lunch-box', 'monde']::text[]),
  ('salade-pates-poulet-pesto-carottes', 'Salade de pâtes au poulet, pesto et carottes', 'Des pâtes froides enrobées de pesto, avec du poulet poêlé, des carottes râpées et du parmesan. Elle se tient très bien jusqu''au déjeuner.', 'Se garde 3 jours au réfrigérateur ; se mange froide.', 2, 10, 15, array['salade', 'plat', 'lunch-box']::text[]),
  ('salade-quinoa-pois-chiches-feta', 'Salade de quinoa, pois chiches et feta au citron', 'Du quinoa, des pois chiches, de la feta, des carottes râpées et de l''oignon rouge, à la vinaigrette citronnée et au cumin. Aucun légume qui ramollit, idéal en boîte.', 'Se garde 3 jours au réfrigérateur ; se mange froide.', 2, 15, 15, array['salade', 'plat', 'lunch-box', 'economique']::text[]),
  ('salade-riz-complet-poulet-cacahuetes', 'Salade de riz complet au poulet, carottes et cacahuètes', 'Du riz complet, du poulet émincé, des carottes et de l''oignon rouge, dans une sauce soja, citron vert et sésame, parsemés de cacahuètes concassées.', 'Se garde 3 jours au réfrigérateur ; ajouter les cacahuètes au moment de manger.', 2, 15, 30, array['salade', 'plat', 'lunch-box', 'monde']::text[]),
  ('wraps-poulet-curry-yaourt-carottes', 'Wraps au poulet curry, yaourt et carottes', 'Des tortillas roulées autour de poulet au curry refroidi, de carottes râpées, de salade et d''une sauce au yaourt. On prépare la garniture la veille, on roule le matin.', 'La garniture se garde 3 jours au réfrigérateur ; rouler les wraps le jour même.', 2, 15, 8, array['plat', 'lunch-box', 'monde']::text[]),
  ('salade-lentilles-betterave-chevre-noix', 'Salade de lentilles, betterave, chèvre et noix', 'Des lentilles vertes en vinaigrette moutardée avec des dés de betterave, de l''oignon rouge, du chèvre émietté et des noix. Encore meilleure après une nuit au frais.', 'Se garde 3 jours au réfrigérateur ; ajouter les noix au moment de manger.', 2, 10, 25, array['salade', 'plat', 'lunch-box', 'economique']::text[]),
  ('salade-piemontaise-jambon-oeufs', 'Salade piémontaise au jambon et aux œufs', 'Des pommes de terre en dés, des œufs durs, du jambon et des cornichons, liés d''une sauce mayonnaise allégée au yaourt et à la moutarde. Le classique des boîtes à déjeuner.', 'Se garde 2 jours au réfrigérateur ; se mange froide.', 2, 15, 20, array['salade', 'plat', 'lunch-box', 'economique']::text[]),
  ('bento-riz-saumon-soja-brocoli', 'Bento riz, saumon laqué au soja et brocoli', 'Du riz, des morceaux de saumon laqués à la sauce soja et au miel, et du brocoli cuit avec le riz, parsemés de sésame. Bon froid comme réchauffé.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 20, array['plat', 'lunch-box', 'monde']::text[]),
  ('muffins-oeufs-jambon-poireau', 'Muffins aux œufs, jambon et poireau', 'Des petits flans aux œufs garnis de poireau fondu, de jambon et d''emmental, cuits au four dans un moule à muffins. Ils se mangent froids, avec une salade de carottes.', 'Se gardent 3 jours au réfrigérateur ; se mangent froids.', 2, 15, 25, array['plat', 'four', 'lunch-box', 'economique']::text[]),
  ('chili-haricots-rouges-riz-boite', 'Chili de haricots rouges et riz en boîte', 'Des haricots rouges mijotés dans une sauce tomate au cumin et au paprika, servis sur du riz avec du cheddar et du yaourt. Il se réchauffe parfaitement au micro-ondes du bureau.', 'Se garde 3 jours au réfrigérateur ou 2 mois au congélateur.', 2, 10, 25, array['plat', 'lunch-box', 'economique', 'monde']::text[]),
  ('salade-boulgour-poulet-carottes-raisins', 'Salade de boulgour au poulet, carottes et raisins', 'Du boulgour aux épices douces, avec du poulet poêlé, des carottes râpées, des raisins secs et une vinaigrette au citron. Le couscous froid qui ne craint pas le trajet.', 'Se garde 3 jours au réfrigérateur ; se mange froide.', 2, 15, 15, array['salade', 'plat', 'lunch-box', 'monde']::text[]),
  ('gratin-penne-brocoli-jambon', 'Gratin de penne au brocoli et au jambon', 'Des penne et du brocoli dans une béchamel légère au lait, avec du jambon et de l''emmental gratiné. Préparé le dimanche, réchauffé toute la semaine.', 'Se garde 3 jours au réfrigérateur ; réchauffer au micro-ondes ou au four.', 2, 15, 30, array['plat', 'four', 'lunch-box', 'economique']::text[]),
  ('falafels-four-pois-chiches-yaourt', 'Falafels au four, carottes et sauce yaourt', 'Des boulettes de pois chiches mixés au cumin et à l''oignon, cuites au four sans friture, servies avec une sauce au yaourt citronnée et des carottes râpées. Elles se mangent froides.', 'Se gardent 3 jours au réfrigérateur ; se mangent froids ou réchauffés.', 2, 20, 25, array['plat', 'four', 'lunch-box', 'economique', 'monde']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

