from (values
  ('soupe-lentilles-vertes-lardons-carottes', 1, 'Émincer l''oignon et le poireau et couper les carottes en rondelles.'),
  ('soupe-lentilles-vertes-lardons-carottes', 2, 'Faire revenir les lardons 3 minutes à sec dans un faitout, puis ajouter l''oignon et le poireau 3 minutes.'),
