  ('salade-boulgour-poulet-carottes-raisins', 3, 'Râper les carottes.'),
  ('salade-boulgour-poulet-carottes-raisins', 4, 'Mélanger le boulgour avec le poulet, les carottes, le jus de citron, le reste de l''huile et la menthe.'),
  ('gratin-penne-brocoli-jambon', 1, 'Préchauffer le four à 200 °C. Cuire les penne dans une casserole d''eau bouillante salée selon le temps indiqué, en ajoutant le brocoli en fleurettes pour les 4 dernières minutes, puis égoutter.'),
  ('gratin-penne-brocoli-jambon', 2, 'Dans la même casserole, faire fondre le beurre, ajouter la farine et mélanger 1 minute, puis verser le lait en fouettant jusqu''à épaississement.'),
  ('gratin-penne-brocoli-jambon', 3, 'Assaisonner la béchamel de muscade, de sel et de poivre, et y mélanger les pâtes, le brocoli et le jambon en morceaux.'),
  ('gratin-penne-brocoli-jambon', 4, 'Verser dans un plat, couvrir d''emmental et enfourner 15 minutes : le dessus doit être doré.'),
  ('falafels-four-pois-chiches-yaourt', 1, 'Préchauffer le four à 200 °C et huiler une plaque.'),
  ('falafels-four-pois-chiches-yaourt', 2, 'Mixer les pois chiches égouttés avec l''oignon, l''ail, le cumin, l''œuf, la farine, le persil et du sel, jusqu''à obtenir une pâte qui se tient.'),
  ('falafels-four-pois-chiches-yaourt', 3, 'Former des boulettes aplaties, les poser sur la plaque et les badigeonner d''huile.'),
  ('falafels-four-pois-chiches-yaourt', 4, 'Enfourner 25 minutes en les retournant à mi-parcours : elles doivent être dorées.'),
  ('falafels-four-pois-chiches-yaourt', 5, 'Servir avec le yaourt au jus de citron, les carottes râpées et le pain.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('soupe-lentilles-vertes-lardons-carottes', 'minestrone-hiver-haricots-rouges-pates', 'veloute-butternut-pois-chiches-feta', 'soupe-thai-poulet-coco-nouilles', 'soupe-poireaux-pommes-de-terre-jambon', 'harira-express-lentilles-pois-chiches', 'soupe-poulet-petites-pates-carottes', 'soupe-patate-douce-lentilles-gingembre', 'salade-pates-poulet-pesto-carottes', 'salade-quinoa-pois-chiches-feta', 'salade-riz-complet-poulet-cacahuetes', 'wraps-poulet-curry-yaourt-carottes', 'salade-lentilles-betterave-chevre-noix', 'salade-piemontaise-jambon-oeufs', 'bento-riz-saumon-soja-brocoli', 'muffins-oeufs-jambon-poireau', 'chili-haricots-rouges-riz-boite', 'salade-boulgour-poulet-carottes-raisins', 'gratin-penne-brocoli-jambon', 'falafels-four-pois-chiches-yaourt')) <> 211 then
    raise exception 'Lignes d''ingrédients manquantes dans le dix-septième lot de recettes.';
  end if;
end;
$$;
